+static void ui_demo_ai_voice_event(lv_event_t *event)
+{
+  struct ui_demo_ai_snapshot snapshot;
+  lv_obj_t *target;
+  bool enabled;
+
+  if (lv_event_get_code(event) != LV_EVENT_VALUE_CHANGED)
+    {
+      return;
