static int pwm_setup(struct pwm_lowerhalf_s *dev)
{
  struct aic_pwm_lowerhalf_s *priv = to_aic_pwm(dev);
  struct aic_pwm_action action0 = {
    .CBD = PWM_ACT_NONE,
    .CBU = PWM_ACT_NONE,
