#include <nuttx/config.h>

#define LVGL_APP_BACKLIGHT_TAG "backlight"

#define LVGL_APP_AIC_PWM_BASE 0x19240000u
#define LVGL_APP_AIC_PWM_CLK_RATE 48000000u
#define LVGL_APP_AIC_PWM_MAX_CHANNELS 4
#define LVGL_APP_AIC_PWM_CTL 0x000u
#define LVGL_APP_AIC_PWM_MCTL 0x004u
#define LVGL_APP_AIC_PWM_CKCTL 0x008u
#define LVGL_APP_AIC_PWM_CHANNEL_BASE 0x300u
#define LVGL_APP_AIC_PWM_CHANNEL_STRIDE 0x100u
#define LVGL_APP_AIC_PWM_TBCTL 0x000u
#define LVGL_APP_AIC_PWM_TBPRD 0x014u
#define LVGL_APP_AIC_PWM_CMPCTL 0x018u
#define LVGL_APP_AIC_PWM_CMPA 0x020u
#define LVGL_APP_AIC_PWM_CMPB 0x024u
#define LVGL_APP_AIC_PWM_AQCTLA 0x028u
#define LVGL_APP_AIC_PWM_AQCTLB 0x02cu
#define LVGL_APP_AIC_PWM_CTL_EN (1u << 0)
#define LVGL_APP_AIC_PWM_CMPCTL_SHADOW_ZRO_PRD 0x0au
#define LVGL_APP_AIC_PWM_TBCTL_CLKDIV_SHIFT 16
#define LVGL_APP_AIC_PWM_TBCTL_CLKDIV_MASK (0x0fffu << 16)
#define LVGL_APP_AIC_PWM_TBCTL_MODE_MASK 0x3u
#define LVGL_APP_AIC_PWM_AQCTLA_BACKLIGHT 0x12u
#define LVGL_APP_AIC_PWM_AQCTLB_BACKLIGHT 0x102u

static int g_backlight_fd = -1;
static bool g_backlight_applied;
static bool g_backlight_warned;
static int32_t g_backlight_percent = -1;

static int32_t lvgl_app_backlight_clamp(int32_t percent)
{
  int32_t min_percent = CONFIG_LVGL_APP_BACKLIGHT_MIN_PERCENT;

  if (min_percent < 1)
    {
      min_percent = 1;
    }
  else if (min_percent > 100)
    {
      min_percent = 100;
    }

  if (percent < 0)
    {
      return min_percent;
    }

  if (percent > 100)
    {
      return 100;
    }

  if (percent < min_percent)
    {
      return min_percent;
    }

  return percent;
}

#ifdef CONFIG_PWM
static uint32_t lvgl_app_backlight_read_pwm(uint32_t offset)
{
  return *(volatile uint32_t *)(uintptr_t)(LVGL_APP_AIC_PWM_BASE + offset);
}

static void lvgl_app_backlight_write_pwm(uint32_t offset, uint32_t value)
{
  *(volatile uint32_t *)(uintptr_t)(LVGL_APP_AIC_PWM_BASE + offset) = value;
  __asm__ __volatile__("" : : : "memory");
}

static uint32_t lvgl_app_backlight_channel_offset(int channel,
                                                  uint32_t reg)
{
  return LVGL_APP_AIC_PWM_CHANNEL_BASE +
         (uint32_t)channel * LVGL_APP_AIC_PWM_CHANNEL_STRIDE + reg;
}

static int lvgl_app_backlight_pwm_channel(void)
{
  const char *path = CONFIG_LVGL_APP_BACKLIGHT_PWM_PATH;
  int channel = -1;
  int value = -1;
  int i;

  for (i = 0; path[i] != '\0'; i++)
    {
      if (path[i] >= '0' && path[i] <= '9')
        {
          if (value < 0)
            {
              value = 0;
            }

          value = value * 10 + path[i] - '0';
        }
      else if (value >= 0)
        {
          channel = value;
          value = -1;
        }
    }

  if (value >= 0)
    {
      channel = value;
    }

  if (channel < 0 || channel >= LVGL_APP_AIC_PWM_MAX_CHANNELS)
    {
      return -ENODEV;
    }

  return channel;
}

static int lvgl_app_backlight_calc_period(uint32_t frequency,
                                           uint32_t *div,
                                           uint32_t *period)
{
  uint32_t candidate;
  uint32_t ticks;

  if (frequency == 0 || div == NULL || period == NULL)
    {
      return -EINVAL;
    }

  for (candidate = 0; candidate <= 0x0fffu; candidate++)
    {
      ticks = (LVGL_APP_AIC_PWM_CLK_RATE / (candidate + 1u)) / frequency;
      if (ticks > 0 && ticks <= 0x10000u)
        {
          *div = candidate;
          *period = ticks - 1u;
          return 0;
        }
    }

  return -ERANGE;
}

static uint32_t lvgl_app_backlight_compare(uint32_t period,
                                           int32_t percent)
{
  uint64_t compare;

  compare = ((uint64_t)period * (uint64_t)percent + 50u) / 100u;
  if (percent >= 100 && compare == period)
    {
      compare++;
    }

  return (uint32_t)compare;
}

static int lvgl_app_backlight_apply_direct(int32_t percent)
{
  uint32_t div;
  uint32_t period;
  uint32_t compare;
  uint32_t offset;
  uint32_t reg;
  int channel;
  int ret;

  channel = lvgl_app_backlight_pwm_channel();
  if (channel < 0)
    {
      return channel;
    }

  ret = lvgl_app_backlight_calc_period(
    CONFIG_LVGL_APP_BACKLIGHT_DIRECT_PWM_FREQUENCY, &div, &period);
  if (ret < 0)
    {
      return ret;
    }

  compare = lvgl_app_backlight_compare(period, percent);

  reg = lvgl_app_backlight_read_pwm(LVGL_APP_AIC_PWM_CTL);
  lvgl_app_backlight_write_pwm(LVGL_APP_AIC_PWM_CTL,
                               reg | LVGL_APP_AIC_PWM_CTL_EN);

  reg = lvgl_app_backlight_read_pwm(LVGL_APP_AIC_PWM_CKCTL);
  lvgl_app_backlight_write_pwm(LVGL_APP_AIC_PWM_CKCTL,
                               reg | (1u << channel));

  offset = lvgl_app_backlight_channel_offset(channel,
                                             LVGL_APP_AIC_PWM_TBCTL);
  reg = lvgl_app_backlight_read_pwm(offset);
  reg &= ~(LVGL_APP_AIC_PWM_TBCTL_CLKDIV_MASK |
           LVGL_APP_AIC_PWM_TBCTL_MODE_MASK);
  reg |= div << LVGL_APP_AIC_PWM_TBCTL_CLKDIV_SHIFT;
  lvgl_app_backlight_write_pwm(offset, reg);

  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_CMPCTL),
    LVGL_APP_AIC_PWM_CMPCTL_SHADOW_ZRO_PRD);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_TBPRD),
    period);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_CMPA),
    compare);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_CMPB),
    compare);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_AQCTLA),
    LVGL_APP_AIC_PWM_AQCTLA_BACKLIGHT);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_AQCTLB),
    LVGL_APP_AIC_PWM_AQCTLB_BACKLIGHT);

  reg = lvgl_app_backlight_read_pwm(LVGL_APP_AIC_PWM_MCTL);
  lvgl_app_backlight_write_pwm(LVGL_APP_AIC_PWM_MCTL,
                               reg | (1u << channel));

  return 0;
}

static void lvgl_app_backlight_disable_direct(void)
{
  int channel;
  uint32_t reg;

  channel = lvgl_app_backlight_pwm_channel();
  if (channel < 0)
    {
      return;
    }

  reg = lvgl_app_backlight_read_pwm(LVGL_APP_AIC_PWM_MCTL);
  lvgl_app_backlight_write_pwm(LVGL_APP_AIC_PWM_MCTL,
                               reg & ~(1u << channel));
}

static int lvgl_app_backlight_open(void)
{
  if (g_backlight_fd >= 0)
    {
      return 0;
    }

  if (CONFIG_LVGL_APP_BACKLIGHT_PWM_PATH[0] == '\0')
    {
      return -ENODEV;
    }

  g_backlight_fd = open(CONFIG_LVGL_APP_BACKLIGHT_PWM_PATH, O_RDWR);
  if (g_backlight_fd < 0)
    {
      if (!g_backlight_warned)
        {
          syslog(LOG_WARNING, "%s: open %s failed errno=%d\n",
                 LVGL_APP_BACKLIGHT_TAG,
                 CONFIG_LVGL_APP_BACKLIGHT_PWM_PATH, errno);
          g_backlight_warned = true;
        }

      return -errno;
    }

  g_backlight_warned = false;
  return 0;
}
#endif

int lvgl_app_backlight_set_percent(int32_t percent)
{
#ifdef CONFIG_PWM
  int ret;

  percent = lvgl_app_backlight_clamp(percent);
  if (g_backlight_applied && g_backlight_percent == percent)
    {
      return 0;
    }

  ret = lvgl_app_backlight_open();
  if (ret < 0)
    {
      return ret;
    }

  ret = lvgl_app_backlight_apply_direct(percent);
  if (ret < 0)
    {
      syslog(LOG_WARNING, "%s: direct pwm apply failed percent=%ld ret=%d\n",
             LVGL_APP_BACKLIGHT_TAG, (long)percent, ret);
      return ret;
    }

  g_backlight_applied = true;
  g_backlight_percent = percent;
  return 0;
#else
  (void)percent;
  return -ENODEV;
#endif
}

void lvgl_app_backlight_shutdown(void)
{
#ifdef CONFIG_PWM
  if (g_backlight_fd >= 0)
    {
      lvgl_app_backlight_disable_direct();
      close(g_backlight_fd);
      g_backlight_fd = -1;
    }

  g_backlight_applied = false;
  g_backlight_percent = -1;
#endif
}
