    if (ret < 0) {
      hal_log_err("Failed to disable PWM%d before restart: %d\n", priv->pwm_id, ret);
      return ret;
    }
    priv->enabled = false;
  }

  period_ns = PWM_10M_Hz_ns / info->frequency;

  for (i = 0; i < CONFIG_PWM_NCHANNELS; i++) {
