static int pwm_fd = -1;

static int panel_backlight_init(void) {
  if (pwm_fd < 0) {
    pwm_fd = open(AIC_PANEL_BACKLIGHT, O_RDWR);
    if (pwm_fd < 0) {
      return -1;
    }
  }
  return 0;
}

void panel_backlight_enable(struct aic_panel *panel, u32 ms) {
  struct pwm_info_s info;
  int ret;

#ifdef CONFIG_AIC_PM_INDEPENDENT_POWER_KEY
  if (panel && panel->independent_pwkey)
    return;
#endif
#ifdef CONFIG_AIC_PANEL_ENABLE_GPIO
  unsigned int g, p;
  long pin;

  pin = hal_gpio_name2pin(AIC_PANEL_ENABLE_GPIO);

  g = GPIO_GROUP(pin);
  p = GPIO_GROUP_PIN(pin);

  hal_gpio_direction_output(g, p);

#ifndef AIC_PANEL_ENABLE_GPIO_LOW
  hal_gpio_set_output(g, p);
#else
  hal_gpio_clr_output(g, p);
#endif
#endif /* AIC_PANEL_ENABLE_GPIO */

  /* Vela system backlight control using NuttX PWM driver */
  if (panel_backlight_init() < 0) {
    return;
  }

  memset(&info, 0, sizeof(info));
  info.frequency = 60000;
  info.duty = 0xffff; /* 100% duty cycle */
#ifndef CONFIG_PWM_MULTICHAN
  info.cpol = PWM_CPOL_NDEF;
  info.dcpol = PWM_DCPOL_NDEF;
#endif

  ret = ioctl(pwm_fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)&info);
  if (ret < 0) {
    return;
  }
static int hal_pwm_calculate_div(u32 ch, float tar_freq) {
  struct aic_pwm_arg *arg = &g_pwm_args[ch];
  int div = -1, i = 0;
  float min_error = 5e6;

  if (tar_freq <= 0.0f) {
    hal_log_err("target freq is invalid.\n");
    return -1;
  }

  for (i = 0; i < PWM_TBCTL_CLKDIV_MAX; ++i) {
    int count_value = arg->clk_rate / ((i + 1) * tar_freq);
    if (count_value <= 0) {
      break;
    }

    if (count_value < PWM_TBPRD_MAX) {
      float current_freq =
          (float)arg->clk_rate / ((float)(i + 1) * (float)count_value);
      float error = fabs(current_freq - tar_freq);

      if (error < min_error) {
        min_error = error;
        div = i;
      }

