  }
  pr_info("fb0 allocated at 0x%x\n", (u32)(uintptr_t)fbi->fb_start);

  fb_color_block(fbi, fb_size);
#endif

  aicfb_probed = true;
  fbi->power_on = false;
  aicfb_set_drvdata(fbi);

