         (unsigned long)fb->paninfo_count);
  fb->paninfo = kmm_zalloc(sizeof(struct fb_paninfo_s) * fb->paninfo_count);

  if (fb->paninfo == NULL)
    {
      gerr("ERROR: alloc panbuf failed\n");
      goto errout_with_fb;
    }

  for (i = 0; i < fb->paninfo_count; i++)
    {
      syslog(LOG_INFO, "fb_register_device: panelinfo begin i=%ld\n",
             (long)i);
      ret = fb_get_panelinfo(fb, &panelinfo, i - 1);
      syslog(LOG_INFO,
             "fb_register_device: panelinfo ret=%d mem=%p len=%lu count=%u bpp=%u\n",
             ret, panelinfo.fbmem, (unsigned long)panelinfo.fblen,
             panelinfo.fbcount, panelinfo.bpp);
      if (ret < 0)
        {
          goto errout_with_paninfo;
        }

      syslog(LOG_INFO, "fb_register_device: circbuf begin i=%ld size=%lu\n",
             (long)i,
             (unsigned long)(panelinfo.fbcount *
                             sizeof(union fb_paninfo_u)));
      ret = circbuf_init(&(fb->paninfo[i].buf), NULL, panelinfo.fbcount
                         * sizeof(union fb_paninfo_u));
      syslog(LOG_INFO, "fb_register_device: circbuf ret=%d\n", ret);

      DEBUGASSERT(ret == 0);

      fb->paninfo[i].dev = fb;

      /* Clear the framebuffer memory */

      syslog(LOG_INFO, "fb_register_device: memset begin mem=%p len=%lu\n",
             panelinfo.fbmem, (unsigned long)panelinfo.fblen);
      memset(panelinfo.fbmem, 0, panelinfo.fblen);
      syslog(LOG_INFO, "fb_register_device: memset done\n");
    }

  /* Register the framebuffer device */

  if (nplanes < 2)
    {
      snprintf(devname, sizeof(devname), "/dev/fb%d", display);
    }

